from __future__ import annotations

import functools
import threading
import time
from collections import OrderedDict
from typing import Any, Callable, Hashable, TypeVar

T = TypeVar("T")
K = TypeVar("K", bound=Hashable)

class LRUCache:
    def __init__(self, maxsize: int = 128, ttl: float = 60.0) -> None:
        if maxsize <= 0:
            raise ValueError("maxsize must be positive")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.maxsize = maxsize
        self.ttl = ttl
        self._data: OrderedDict[K, tuple[Any, float]] = OrderedDict()
        self._lock = threading.RLock()

    def _is_expired(self, timestamp: float) -> bool:
        return (time.monotonic() - timestamp) >= self.ttl

    def get(self, key: K) -> Any | None:
        with self._lock:
            item = self._data.get(key)
            if item is None:
                return None
            value, timestamp = item
            if self._is_expired(timestamp):
                self._data.pop(key, None)
                return None
            self._data.move_to_end(key)
            return value

    def set(self, key: K, value: Any) -> None:
        with self._lock:
            if key in self._data:
                self._data.pop(key)
            self._data[key] = (value, time.monotonic())
            self._data.move_to_end(key)
            while len(self._data) > self.maxsize:
                self._data.popitem(last=False)

    def clear(self) -> None:
        with self._lock:
            self._data.clear()

    def __len__(self) -> int:
        with self._lock:
            self._data = OrderedDict((k, v) for k, v in self._data.items() if not self._is_expired(v[1]))
            return len(self._data)

def cache(maxsize: int = 128, ttl: float = 60.0) -> Callable[[Callable[..., T]], Callable[..., T]]:
    def decorator(func: Callable[..., T]) -> Callable[..., T]:
        store: LRUCache = LRUCache(maxsize=maxsize, ttl=ttl)

        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> T:
            key = (args, tuple(sorted(kwargs.items())))
            cached = store.get(key)
            if cached is not None:
                return cached
            result = func(*args, **kwargs)
            store.set(key, result)
            return result

        wrapper.cache_clear = store.clear  # type: ignore[attr-defined]
        return wrapper

    return decorator

