interface User {
  id: string | number;
  orgId: string | number;
  org?: Org;
  [key: string]: unknown;
}

interface Org {
  id: string | number;
  [key: string]: unknown;
}

async function loadUser(id: string | number): Promise<User> {
  const response = await fetch(`/api/users/${id}`);
  if (!response.ok) {
    throw new Error(`Failed to load user ${id}: bad status ${response.status}`);
  }

  const user = (await response.json()) as User;

  const orgResponse = await fetch(`/api/orgs/${user.orgId}`);
  if (!orgResponse.ok) {
    throw new Error(`Failed to load org ${user.orgId}: bad status ${orgResponse.status}`);
  }

  user.org = (await orgResponse.json()) as Org;
  return user;
}

async function loadUsers(ids: Array<string | number>): Promise<User[]> {
  return Promise.all(ids.map((id) => loadUser(id)));
}

